16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    @Email
55	    private String email;
56	
57	    @Column(name = "postcode")
58	    private String postcode;
59	
60	    @Column(name = "registration_date")
61	    private LocalDate registrationDate;
62	
63	    @Column(name = "customer_code")
64	    private String customerCode;
65	
66	    @Column(name = "household_id")
67	    private String householdId;
68	
69	    @Column(name = "namesake_count")
70	    private Integer namesakeCount;
71	
72	    @Column(name = "membership_number")
73	    private String membershipNumber;
74	
75	    @Column(name = "bulk_signup_warning")
76	    private Boolean bulkSignupWarning;
77	
78	    @Column(name = "household_size")
79	    private Integer householdSize;
80	
81	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
82	    private Set<Pet> pets;
83	
84	    public String getAddress() {
85	        return this.address;
86	    }
87	
88	    public void setAddress(String address) {
89	        this.address = address;
90	    }
91	
92	    public String getCity() {
93	        return this.city;
94	    }
95	
96	    public void setCity(String city) {
97	        this.city = city;
98	    }
99	
100	    /**
101	     * The owner's locality, i.e. the canonical region it belongs to (read from the
102	     * assigned {@link #customerCode} when present, otherwise derived from the owner's
103	     * own fields via {@link #regionForOwner()}). Derived (not persisted); recomputed
104	     * each call. See {@link OwnerDerivations#locality(String, String, String)} for the
105	     * full derivation.
106	     *
107	     * @return the canonical region string, or {@code "UNKNOWN"}
108	     */
109	    @Transient
110	    public String getLocality() {
111	        return OwnerDerivations.locality(this.customerCode, this.postcode, this.city);
112	    }
113	
114	    /**
115	     * The canonical region derived for this owner from its own fields. Recomputed each
116	     * call. See {@link OwnerDerivations#region(String, String)} for the derivation.
117	     *
118	     * @return the canonical region string, or {@code "UNKNOWN"}
119	     */
120	    public String regionForOwner() {
121	        return OwnerDerivations.region(this.postcode, this.city);
122	    }
123	
124	    /**
125	     * Whether this owner's postcode is consistent with its {@link #getLocality()
126	     * locality}: an absent postcode is accepted, a present one must be exactly four
127	     * digits and, when the locality has a known postcode range, fall within it. See
128	     * {@link OwnerDerivations#postcodeMatchesRegion(String, String)}.
129	     *
130	     * @return {@code true} if the postcode is absent or valid for the owner's locality
131	     */
132	    public boolean postcodeValidForLocality() {
133	        return OwnerDerivations.postcodeMatchesRegion(this.postcode, this.getLocality());
134	    }
135	
136	    /**
137	     * The owner's membership level, a number from 1 to 3. Derived (not persisted);
138	     * recomputed from the current fields each call. See
139	     * {@link OwnerDerivations#membershipLevel(String, Integer)} for how it is assigned.
140	     *
141	     * @return the membership level, from 1 to 3
142	     */
143	    @Transient
144	    public Integer getMembershipLevel() {
145	        return OwnerDerivations.membershipLevel(this.email, this.namesakeCount);
146	    }
147	
148	    /**
149	     * The owner's preferred contact channel, {@code "EMAIL"} or {@code "PHONE"}.
150	     * Derived (not persisted); recomputed from the current fields each call. See
151	     * {@link OwnerDerivations#contactPreference(String)}.
152	     *
153	     * @return {@code "EMAIL"} or {@code "PHONE"}
154	     */
155	    @Transient
156	    public String getContactPreference() {
157	        return OwnerDerivations.contactPreference(this.email);
158	    }
159	
160	    public String getTelephone() {
161	        return this.telephone;
162	    }
163	
164	    public void setTelephone(String telephone) {
165	        this.telephone = telephone;
166	    }
167	
168	    public String getEmail() {
169	        return this.email;
170	    }
171	
172	    public void setEmail(String email) {
173	        this.email = email;
174	    }
175	
176	    public String getPostcode() {
177	        return this.postcode;
178	    }
179	
180	    public void setPostcode(String postcode) {
181	        this.postcode = postcode;
182	    }
183	
184	    public LocalDate getRegistrationDate() {
185	        return this.registrationDate;
186	    }
187	
188	    public void setRegistrationDate(LocalDate registrationDate) {
189	        this.registrationDate = registrationDate;
190	    }
191	
192	    public String getCustomerCode() {
193	        return this.customerCode;
194	    }
195	
196	    public void setCustomerCode(String customerCode) {
197	        this.customerCode = customerCode;
198	    }
199	
200	    /**
201	     * The Luhn check digit (0-9) computed over the digits in this owner's
202	     * {@link #customerCode}. Derived (not persisted); recomputed each call. See
203	     * {@link OwnerDerivations#checkDigit(String)}.
204	     *
205	     * @return the Luhn check digit, from 0 to 9
206	     */
207	    @Transient
208	    public Integer getCheckDigit() {
209	        return OwnerDerivations.checkDigit(this.customerCode);
210	    }
211	
212	    public String getHouseholdId() {
213	        return this.householdId;
214	    }
215	
216	    public void setHouseholdId(String householdId) {
217	        this.householdId = householdId;
218	    }
219	
220	    public Integer getNamesakeCount() {
221	        return this.namesakeCount;
222	    }
223	
224	    public void setNamesakeCount(Integer namesakeCount) {
225	        this.namesakeCount = namesakeCount;
226	    }
227	
228	    public String getMembershipNumber() {
229	        return this.membershipNumber;
230	    }
231	
232	    public void setMembershipNumber(String membershipNumber) {
233	        this.membershipNumber = membershipNumber;
234	    }
235	
236	    public Boolean getBulkSignupWarning() {
237	        return this.bulkSignupWarning;
238	    }
239	
240	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
241	        this.bulkSignupWarning = bulkSignupWarning;
242	    }
243	
244	    public Integer getHouseholdSize() {
245	        return this.householdSize;
246	    }
247	
248	    public void setHouseholdSize(Integer householdSize) {
249	        this.householdSize = householdSize;
250	    }
251	
252	    /**
253	     * The derived key used for duplicate detection, combining this owner's normalised
254	     * telephone, email and {@link #householdId}. Two owners are duplicates exactly when
255	     * their whole identity keys are equal, so members of the same household with
